-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — ŠVÉDSKO (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Švédsko – Skåne: Ales stenar a Kullaberg
  delete from public.routes where name = 'Švédsko – Skåne: Ales stenar a Kullaberg' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Skåne: Ales stenar a Kullaberg', 'Velký okruh nejjižnější švédskou provincií spojuje dvě naprosto odlišné tváře Skåne — skalnatý mys Kullaberg s majákem nad Öresundem a mystický kamenný kruh Ales stenar vysoko nad Baltem. Jede se po klidných silnicích mezi řepkovými poli, hrázděnými statky a bílými kostelíky, provoz je mimo Malmö minimální. Cestou stojí za zastávku katedrála v Lundu i středověká věž Kärnan v Helsingborgu, odkud je vidět až do Dánska. Závěr patří pobřeží Österlen, které Švédové sami považují za svou nejkrásnější krajinu. Nejlepší období je květen až září; u moře počítej s větrem a na jaře se žlutými koberci řepky, které lákají k fotopauzám. Silnice jsou v perfektním stavu, jen dodržuj přísné švédské limity.', 'loop', 360, 400, 'easy',
     '[{"lat": 55.6050, "lng": 13.0038, "label": "Start: Malmö"}, {"lat": 55.7047, "lng": 13.1932, "label": "Lund"}, {"lat": 56.0465, "lng": 12.6945, "label": "Helsingborg"}, {"lat": 56.2870, "lng": 12.4980, "label": "Mölle – Kullaberg"}, {"lat": 55.4295, "lng": 13.8204, "label": "Ystad"}, {"lat": 55.3855, "lng": 14.0533, "label": "Kåseberga"}, {"lat": 55.6050, "lng": 13.0038, "label": "Cíl: Malmö"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=55.6050,13.0038&destination=55.6050,13.0038&travelmode=driving&waypoints=55.7047,13.1932%7C56.0465,12.6945%7C56.2870,12.4980%7C55.4295,13.8204%7C55.3855,14.0533', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ales_stenar_bred.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turning_Torso.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lunds_domkyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%A4rnan.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kullens_fyr.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ales_stenar_bred.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glimmingehus.jpg"}'::text[], '{"Turning Torso (Malmö)","Katedrála v Lundu","Věž Kärnan (Helsingborg)","Maják Kullens fyr","Ales stenar","Hrad Glimmingehus"}'::text[], '{"SE"}'::text[], false, 5110, 'approved');

  -- Švédsko – Öland: ostrov větrných mlýnů a majáků
  delete from public.routes where name = 'Švédsko – Öland: ostrov větrných mlýnů a majáků' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Öland: ostrov větrných mlýnů a majáků', 'Objet celý Öland od majáku k majáku je jeden z nejpohodovějších motorkářských dnů ve Švédsku. Na ostrov se dostaneš po šestikilometrovém Ölandském mostě z Kalmaru a pak už tě čekají rovné pobřežní silničky, stovky dřevěných větrných mlýnů a vápencová step Stora Alvaret zapsaná na seznamu UNESCO. Provoz je mimo červencovou špičku minimální a moře máš skoro pořád na dohled. Krajina je plochá, ale právě ta nekonečná obloha a světlo dělají z Ölandu zážitek — ne nadarmo tu má letní sídlo švédská královská rodina. Nejlépe v červnu nebo září; pozor na silný boční vítr na mostě a na srnky za soumraku.', 'loop', 340, 360, 'easy',
     '[{"lat": 56.6634, "lng": 16.3568, "label": "Start: Kalmar"}, {"lat": 56.8790, "lng": 16.6567, "label": "Borgholm"}, {"lat": 57.3300, "lng": 17.0080, "label": "Byxelkrok"}, {"lat": 56.5530, "lng": 16.5230, "label": "Stora Alvaret"}, {"lat": 56.1980, "lng": 16.3990, "label": "Ottenby"}, {"lat": 56.6634, "lng": 16.3568, "label": "Cíl: Kalmar"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=56.6634,16.3568&destination=56.6634,16.3568&travelmode=driving&waypoints=56.8790,16.6567%7C57.3300,17.0080%7C56.5530,16.5230%7C56.1980,16.3990', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalmar_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kalmar_slott.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C3%96landsbron.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Borgholms_slott.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5nge_Erik.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stora_Alvaret.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5nge_Jan.jpg"}'::text[], '{"Hrad Kalmar","Ölandský most","Zřícenina Borgholm","Maják Långe Erik","Stora Alvaret","Maják Långe Jan (Ottenby)"}'::text[], '{"SE"}'::text[], false, 5120, 'approved');

  -- Švédsko – Gotland: Visby a vápencové rauky
  delete from public.routes where name = 'Švédsko – Gotland: Visby a vápencové rauky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Gotland: Visby a vápencové rauky', 'Gotland je motorkářský ráj uprostřed Baltu — na ostrov tě z Nynäshamnu nebo Oskarshamnu přiveze trajekt (motorku vezmou bez problémů) a pak tě čekají prázdné silnice mezi vápencovými skalami, středověkými kostely a poli vlčích máků. Okruh z hanzovního Visby, města UNESCO obehnaného třiapůlkilometrovou hradbou, projede podél západního pobřeží k raukům u Lickershamnu a přes východní pláže až k jižnímu mysu Hoburgen. Rauky — bizarní vápencové věže vysoké až 12 metrů — nikde jinde v Evropě v takové koncentraci neuvidíš. Silnice jsou úzké, ale kvalitní a téměř bez provozu. Ideální je červen a začátek září; v půlce srpna počítej s návalem během týdne Medeltidsveckan.', 'loop', 250, 300, 'easy',
     '[{"lat": 57.6370, "lng": 18.2948, "label": "Start: Visby"}, {"lat": 57.7440, "lng": 18.4060, "label": "Lummelunda"}, {"lat": 57.8290, "lng": 18.5230, "label": "Lickershamn"}, {"lat": 57.3260, "lng": 18.7080, "label": "Ljugarn"}, {"lat": 56.9210, "lng": 18.1440, "label": "Hoburgen"}, {"lat": 57.6370, "lng": 18.2948, "label": "Cíl: Visby"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=57.6370,18.2948&destination=57.6370,18.2948&travelmode=driving&waypoints=57.7440,18.4060%7C57.8290,18.5230%7C57.3260,18.7080%7C56.9210,18.1440', 'https://commons.wikimedia.org/wiki/Special:FilePath/Visby_ringmur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Visby_ringmur.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lummelundagrottan.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lickershamn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Folhammar.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hoburgsgubben.jpg"}'::text[], '{"Hradby Visby","Jeskyně Lummelunda","Rauk Jungfrun (Lickershamn)","Rauky Folhammar (Ljugarn)","Hoburgsgubben"}'::text[], '{"SE"}'::text[], false, 5130, 'approved');

  -- Švédsko – Velký okruh kolem Vätternu
  delete from public.routes where name = 'Švédsko – Velký okruh kolem Vätternu' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Velký okruh kolem Vätternu', 'Objet druhé největší švédské jezero je klasika, kterou si každý rok dávají tisíce cyklistů — na motorce si ji ale vychutnáš mnohem víc. Východní břeh nabízí panoramatickou jízdu vysoko nad hladinou kolem Gränny a zříceniny Brahehus, západní břeh zase idylická dřevěná městečka Hjo a Askersund. Cestou potkáš klášterní Vadstenu, Göta kanál v Motale i mohutnou pevnost Karlsborg. Voda Vätternu je tak čistá, že se pije bez úpravy, a za jasného dne dohlédneš přes jezero na protější břeh vzdálený 30 kilometrů. Jede se celý den v pohodovém tempu po kvalitních silnicích; nejhezčí je červen se světlem dlouho do noci. Pozor jen na hustší provoz na E4 u Jönköpingu — co nejdřív z ní sjeď na starou pobřežní silnici.', 'loop', 300, 330, 'easy',
     '[{"lat": 57.7815, "lng": 14.1562, "label": "Start: Jönköping"}, {"lat": 58.0250, "lng": 14.4670, "label": "Gränna"}, {"lat": 58.4480, "lng": 14.8900, "label": "Vadstena"}, {"lat": 58.5370, "lng": 15.0360, "label": "Motala"}, {"lat": 58.5360, "lng": 14.5060, "label": "Karlsborg"}, {"lat": 58.3020, "lng": 14.2900, "label": "Hjo"}, {"lat": 57.7815, "lng": 14.1562, "label": "Cíl: Jönköping"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=57.7815,14.1562&destination=57.7815,14.1562&travelmode=driving&waypoints=58.0250,14.4670%7C58.4480,14.8900%7C58.5370,15.0360%7C58.5360,14.5060%7C58.3020,14.2900', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vadstena_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gyllene_Uttern.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%A4nna_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brahehus.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vadstena_slott.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%B6ta_kanal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karlsborgs_f%C3%A4stning.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hjo_kyrka.jpg"}'::text[], '{"Restaurace: Gyllene Uttern (Gränna)","Gränna – městečko polkagrisů","Zřícenina Brahehus","Vadstena – zámek a klášter","Göta kanál (Motala)","Pevnost Karlsborg","Hjo – dřevěné městečko"}'::text[], '{"SE"}'::text[], false, 5140, 'approved');

  -- Švédsko – Bohuslän: žulové pobřeží a Smögen
  delete from public.routes where name = 'Švédsko – Bohuslän: žulové pobřeží a Smögen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Bohuslän: žulové pobřeží a Smögen', 'Západní pobřeží mezi Göteborgem a norskou hranicí je souostroví z růžové žuly ohlazené ledovcem — tisíce holých ostrůvků, rybářské vesnice s červenými boudami na kůlech a mosty klenoucí se přes fjordy. Trasa uhýbá z hlavního tahu E6 na pobřežní silničky přes ostrovy Tjörn a Orust, kolem slavného mola ve Smögenu až k prehistorickým rytinám v Tanumu. Úzké silnice se vlní mezi skalami a zálivy, takže se nejede rychle, ale každá zatáčka otevře nový pohled na moře. Cestou ochutnáš to nejlepší ze švédských plodů moře — krevety, ústřice a humry se tu loví přímo před pobřežím. Nejkrásněji je tu v červnu a na přelomu srpna a září, kdy zmizí letní davy; počítej s větrem od moře a v sezóně s kolonami u mostů.', 'poi', 230, 300, 'medium',
     '[{"lat": 57.7089, "lng": 11.9746, "label": "Start: Göteborg"}, {"lat": 57.8880, "lng": 11.5820, "label": "Marstrand"}, {"lat": 58.0107, "lng": 11.8330, "label": "Tjörnbron"}, {"lat": 58.3550, "lng": 11.2270, "label": "Smögen"}, {"lat": 58.5990, "lng": 11.2840, "label": "Fjällbacka"}, {"lat": 58.7000, "lng": 11.3410, "label": "Vitlycke"}, {"lat": 58.9380, "lng": 11.1710, "label": "Cíl: Strömstad"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=57.7089,11.9746&destination=58.9380,11.1710&travelmode=driving&waypoints=57.8880,11.5820%7C58.0107,11.8330%7C58.3550,11.2270%7C58.5990,11.2840%7C58.7000,11.3410', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sm%C3%B6genbryggan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Carlstens_f%C3%A4stning.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tj%C3%B6rnbron.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A4desholmen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sm%C3%B6genbryggan.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fj%C3%A4llbacka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vitlyckeh%C3%A4llen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6mstads_kyrka.jpg"}'::text[], '{"Pevnost Carlsten (Marstrand)","Most Tjörnbron","Restaurace: Salt & Sill (Klädesholmen)","Smögenbryggan","Fjällbacka","Skalní rytiny Vitlycke (UNESCO)","Strömstad"}'::text[], '{"SE"}'::text[], false, 5150, 'approved');

  -- Švédsko – Dalarna: okruh kolem jezera Siljan
  delete from public.routes where name = 'Švédsko – Dalarna: okruh kolem jezera Siljan' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Dalarna: okruh kolem jezera Siljan', 'Siljan je jezero v kráteru po dopadu meteoritu a jeho objetí je koncentrát všeho, co si představíš pod pojmem Švédsko — červené chalupy se slunečnicemi, dřevění koníci dalahäst, zvonice nad jezerem a březové aleje. Okruh spojuje Moru s ateliérem malíře Zorna, manufaktury na koníky v Nusnäs, molo v Rättviku i pohlednicovou vesničku Tällberg na kopci nad hladinou. Ze západního břehu se vyplatí odbočka na vyhlídku Gesundaberget a na závěr srdce medvědího kraje v Orse. Silnice kopírují břeh a příjemně se vlní, provoz je klidný a odpočívadel s výhledem bezpočet. Nejhezčí je doba kolem midsommaru, kdy se u jezera slaví u májek v krojích — a taky nejrušnější. Pozor na losy, zvlášť za šera na lesních úsecích u Orsy.', 'loop', 190, 240, 'easy',
     '[{"lat": 61.0046, "lng": 14.5430, "label": "Start: Mora"}, {"lat": 60.9560, "lng": 14.6640, "label": "Nusnäs"}, {"lat": 60.8830, "lng": 15.1190, "label": "Rättvik"}, {"lat": 60.8230, "lng": 15.0250, "label": "Tällberg"}, {"lat": 60.7310, "lng": 14.9990, "label": "Leksand"}, {"lat": 60.9010, "lng": 14.5220, "label": "Gesunda"}, {"lat": 61.1190, "lng": 14.6180, "label": "Orsa"}, {"lat": 61.0046, "lng": 14.5430, "label": "Cíl: Mora"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=61.0046,14.5430&destination=61.0046,14.5430&travelmode=driving&waypoints=60.9560,14.6640%7C60.8830,15.1190%7C60.7310,14.9990%7C60.9010,14.5220%7C61.1190,14.6180', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dalah%C3%A4st.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zorng%C3%A5rden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dalah%C3%A4st.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A4ttviks_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A4llberg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Leksands_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gesundaberget.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orsa_Gr%C3%B6nklitt.jpg"}'::text[], '{"Zorngården (Mora)","Dřevění koníci v Nusnäs","Rättvik – Långbryggan","Restaurace: Klockargården (Tällberg)","Leksand","Vyhlídka Gesundaberget","Medvědí park Orsa"}'::text[], '{"SE"}'::text[], false, 5160, 'approved');

  -- Švédsko – Höga Kusten: most a NP Skuleskogen
  delete from public.routes where name = 'Švédsko – Höga Kusten: most a NP Skuleskogen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Höga Kusten: most a NP Skuleskogen', 'Vysoké pobřeží mezi Härnösandem a Örnsköldsvikem je jediné místo na světě, kde se pevnina po době ledové zvedla o 286 metrů — vznikly tak strmé žulové kopce padající přímo do Botnického zálivu, krajina zapsaná na seznamu UNESCO. Trasa startuje přejezdem majestátního visutého mostu Högakustenbron a pak uhýbá z E4 na úzké silničky poloostrova Nordingrå k rybářské vesničce Norrfällsviken. Vrcholem je národní park Skuleskogen s rozsedlinou Slåttdalsskrevan — 40 metrů hlubokou puklinou ve skále. Silnice se tu vlní a houpou jako málokde ve Švédsku, výhledy na záliv se střídají s hlubokými lesy. Nejlepší období je od června do začátku září; na vedlejších cestách počítej místy s hrubším asfaltem a v lese s losy.', 'poi', 160, 210, 'medium',
     '[{"lat": 62.6323, "lng": 17.9379, "label": "Start: Härnösand"}, {"lat": 62.7990, "lng": 17.9390, "label": "Högakustenbron"}, {"lat": 62.9640, "lng": 18.2620, "label": "Norrfällsviken"}, {"lat": 63.0570, "lng": 18.3350, "label": "Docksta"}, {"lat": 63.0970, "lng": 18.5030, "label": "Skuleskogen"}, {"lat": 63.2909, "lng": 18.7153, "label": "Cíl: Örnsköldsvik"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=62.6323,17.9379&destination=63.2909,18.7153&travelmode=driving&waypoints=62.7990,17.9390%7C62.9640,18.2620%7C63.0570,18.3350%7C63.0970,18.5030', 'https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%B6gakustenbron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4rn%C3%B6sands_domkyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%B6gakustenbron.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mannaminne.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Norrf%C3%A4llsviken.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skuleberget.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sl%C3%A5ttdalsskrevan.jpg"}'::text[], '{"Härnösand","Most Högakustenbron","Mannaminne (Häggvik)","Norrfällsviken","Skuleberget","Slåttdalsskrevan (NP Skuleskogen)"}'::text[], '{"SE"}'::text[], false, 5170, 'approved');

  -- Švédsko – Värmland: Klarälven a jezero Fryken
  delete from public.routes where name = 'Švédsko – Värmland: Klarälven a jezero Fryken' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Värmland: Klarälven a jezero Fryken', 'Värmland je kraj spisovatelů, hlubokých lesů a dlouhých jezer — a tenhle okruh z Karlstadu ho projede celý. Nejdřív podél dlouhého jezera Fryken krajinou Gösty Berlinga, kolem statku nobelistky Selmy Lagerlöfové v Mårbace a sochařského parku Rottneros, s výšlapem na vyhlídku Tossebergsklätten vysoko nad hladinou. V Torsby se okruh stočí na jih a vrací se údolím řeky Klarälven, po níž se ještě v 90. letech plavilo dřevo — silnice 62 kopíruje její meandry desítky kilometrů. Provoz je řídký, asfalt kvalitní a zatáčky plynulé, ideální na pohodové tempo. Nejhezčí je od června do září; za soumraku zpomal, údolí Klarälvenu je království losů.', 'loop', 270, 310, 'easy',
     '[{"lat": 59.3793, "lng": 13.5036, "label": "Start: Karlstad"}, {"lat": 59.7620, "lng": 13.2680, "label": "Mårbacka"}, {"lat": 59.8360, "lng": 13.1430, "label": "Sunne"}, {"lat": 60.1360, "lng": 12.9990, "label": "Torsby"}, {"lat": 60.1730, "lng": 13.4920, "label": "Ekshärad"}, {"lat": 59.7770, "lng": 13.4260, "label": "Ransäter"}, {"lat": 59.3793, "lng": 13.5036, "label": "Cíl: Karlstad"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=59.3793,13.5036&destination=59.3793,13.5036&travelmode=driving&waypoints=59.7620,13.2680%7C59.8360,13.1430%7C60.1360,12.9990%7C60.1730,13.4920%7C59.7770,13.4260', 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A5rbacka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlstads_domkyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A5rbacka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rottneros_Park.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sunne_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tossebergskl%C3%A4tten.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Eksh%C3%A4rads_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Klar%C3%A4lven.jpg"}'::text[], '{"Karlstad","Mårbacka – statek Selmy Lagerlöfové","Park Rottneros","Restaurace: Broby Gästgivaregård (Sunne)","Vyhlídka Tossebergsklätten","Kostel v Ekshäradu","Meandry řeky Klarälven"}'::text[], '{"SE"}'::text[], false, 5180, 'approved');

  -- Švédsko – Stockholmské souostroví: Vaxholm a Dalarö
  delete from public.routes where name = 'Švédsko – Stockholmské souostroví: Vaxholm a Dalarö' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Stockholmské souostroví: Vaxholm a Dalarö', 'Stockholmské souostroví má 30 000 ostrovů a tenhle okruh posbírá ta nejkrásnější místa, kam se dá dojet po silnici — bez jediného trajektu. Z centra Stockholmu vede přes mosty do pevnostního městečka Vaxholm, pak na poloostrov Värmdö s porcelánkou Gustavsberg a do přístavu Stavsnäs, odkud vyplouvají lodě do vnějšího souostroví. Jižní část projede kapitánskou vesnici Dalarö a končí v přístavu Nynäshamn, odkud odplouvají trajekty na Gotland — okruh se tak dá spojit s gotlandskou trasou. Silnice se vlní mezi žulovými skalami, zálivy a borovicemi, moře je pořád na dosah. Nejlépe ve všední den mimo červencovou špičku, o víkendech tu bývá hustý výletní provoz; na jaře a na podzim počítej s kluzkým jehličím ve stínu lesa.', 'loop', 230, 300, 'easy',
     '[{"lat": 59.3293, "lng": 18.0686, "label": "Start: Stockholm"}, {"lat": 59.4030, "lng": 18.3510, "label": "Vaxholm"}, {"lat": 59.3270, "lng": 18.3860, "label": "Gustavsberg"}, {"lat": 59.2870, "lng": 18.6890, "label": "Stavsnäs"}, {"lat": 59.1320, "lng": 18.4080, "label": "Dalarö"}, {"lat": 58.9030, "lng": 17.9480, "label": "Nynäshamn"}, {"lat": 59.3293, "lng": 18.0686, "label": "Cíl: Stockholm"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=59.3293,18.0686&destination=59.3293,18.0686&travelmode=driving&waypoints=59.4030,18.3510%7C59.3270,18.3860%7C59.2870,18.6890%7C59.1320,18.4080%7C58.9030,17.9480', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kastell.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stockholm_old_town_2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kastell.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gustavsbergs_hamn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dalar%C3%B6_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nyn%C3%A4shamns_kyrka.jpg"}'::text[], '{"Gamla stan (Stockholm)","Pevnost Vaxholm","Restaurace: Hembygdsgårdens Café (Vaxholm)","Gustavsberg – porcelánka","Dalarö","Nynäshamn"}'::text[], '{"SE"}'::text[], false, 5190, 'approved');

  -- Švédsko – Vänern: Läckö, Kinnekulle a Trollhättan
  delete from public.routes where name = 'Švédsko – Vänern: Läckö, Kinnekulle a Trollhättan' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Vänern: Läckö, Kinnekulle a Trollhättan', 'Jižní břeh Vänernu, největšího jezera Evropské unie, schovává trojici klenotů: bílý pohádkový zámek Läckö na samém konci poloostrova Kållandsö, rozkvetlou stolovou horu Kinnekulle a průmyslovou katedrálu vodopádů a zdymadel v Trollhättanu. Okruh startuje u slavných trollhättanských vodopádů, pokračuje rovinatou krajinou k Lidköpingu a pak úzkými silničkami mezi zálivy na Kållandsö. Kinnekulle nabídne jediné pořádné stoupání široko daleko a výhled přes nekonečnou hladinu; dole pod horou stojí kostel v Husaby, kde byl pokřtěn první švédský král. Silnice jsou klidné a rychlé, ideální i pro méně zkušené jezdce. Nejkrásněji je tu v květnu, kdy na Kinnekulle kvetou třešňové sady a česnekové koberce; vodopády v Trollhättanu pouštějí naplno jen v určené časy — ověř si je předem.', 'loop', 250, 290, 'easy',
     '[{"lat": 58.2837, "lng": 12.2886, "label": "Start: Trollhättan"}, {"lat": 58.5035, "lng": 13.1577, "label": "Lidköping"}, {"lat": 58.6740, "lng": 13.2210, "label": "Zámek Läckö"}, {"lat": 58.5950, "lng": 13.3970, "label": "Kinnekulle"}, {"lat": 58.5380, "lng": 13.3820, "label": "Husaby"}, {"lat": 58.2837, "lng": 12.2886, "label": "Cíl: Trollhättan"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=58.2837,12.2886&destination=58.2837,12.2886&travelmode=driving&waypoints=58.5035,13.1577%7C58.6740,13.2210%7C58.5950,13.3970%7C58.5380,13.3820', 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A4ck%C3%B6_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trollh%C3%A4ttefallen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trollh%C3%A4ttans_kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lidk%C3%B6pings_r%C3%A5dhus.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A4ck%C3%B6_slott.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kinnekulle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Husaby_kyrka.jpg"}'::text[], '{"Vodopády a zdymadla Trollhättan","Restaurace: Albert Kök (Trollhättan)","Lidköping","Zámek Läckö","Stolová hora Kinnekulle","Kostel v Husaby"}'::text[], '{"SE"}'::text[], false, 5200, 'approved');

end $$;
