  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Turning Torso (Malmö)', 'Ikonický zkroucený mrakodrap od Santiaga Calatravy je s 190 metry nejvyšší budovou Skandinávie a symbolem moderního Malmö. Stojí ve čtvrti Västra Hamnen přímo u moře — ideální místo na první kávu s výhledem na Öresundský most.', 55.6132, 12.9758, 'https://commons.wikimedia.org/wiki/Special:FilePath/Turning_Torso.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turning_Torso.jpg"}'::text[], 0),
    (v_route, 'Katedrála v Lundu', 'Románská katedrála z 12. století je nejvýznamnější středověkou stavbou Švédska. Uvnitř nezmeškej slavný astronomický orloj Horologium mirabile Lundense, který se dvakrát denně rozehraje. Univerzitní Lund kolem katedrály má atmosféru jako Oxford v malém.', 55.7047, 13.1932, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lunds_domkyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lunds_domkyrka.jpg"}'::text[], 1),
    (v_route, 'Věž Kärnan (Helsingborg)', 'Mohutná cihlová věž ze 14. století je posledním pozůstatkem dánského hradu, který střežil nejužší místo Öresundu. Z vrcholu je za jasného dne krásně vidět dánský Helsingør s hradem Kronborg — Hamletovým Elsinorem — jen 4 kilometry přes úžinu.', 56.0489, 12.6935, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%A4rnan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%A4rnan.jpg"}'::text[], 2),
    (v_route, 'Maják Kullens fyr', 'Nejjasnější maják Skandinávie stojí na dramatickém skalnatém mysu Kullaberg vysoko nad mořem. Poslední kilometry k němu vedou úzkou zatáčkovitou silničkou přírodní rezervací — motorkářská lahůdka. Dole pod útesy se dají objevovat jeskyně a v moři občas zahlédneš sviňuchy.', 56.3009, 12.4520, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kullens_fyr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kullens_fyr.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Store Thor (Ystad)', 'Vyhlášená restaurace ve sklepení středověké radnice na hlavním náměstí v Ystadu, městě známém z detektivek o komisaři Wallanderovi. Skvělá skånská kuchyně — vyzkoušej místní rybí speciality. V létě se sedí venku na dlážděném náměstí.', 55.4296, 13.8210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ystads_r%C3%A5dhus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ystads_r%C3%A5dhus.jpg"}'::text[], 4),
    (v_route, 'Ales stenar', 'Největší kamenná loď Skandinávie — 59 balvanů ve tvaru lodi z doby železné — stojí na travnatém útesu 30 metrů nad mořem u vesničky Kåseberga. Magické místo, zvlášť večer, kdy se nad Baltem barví nebe. Od parkoviště je to 10 minut pěšky do kopce; dole v přístavu prodávají vyhlášené uzené ryby.', 55.3831, 14.0559, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ales_stenar_bred.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ales_stenar_bred.jpg"}'::text[], 5),
    (v_route, 'Hrad Glimmingehus', 'Nejzachovalejší středověká tvrz Skandinávie z roku 1499 vypadá přesně tak, jak si představuješ severský hrad — strohý kamenný blok s metr tlustými zdmi uprostřed polí. Podle pověstí tu straší víc duchů než kdekoli jinde ve Švédsku.', 55.4880, 14.2260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glimmingehus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Glimmingehus.jpg"}'::text[], 6);
  insert into public.routes
