  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Kalmar', 'Renesanční vodní hrad na ostrůvku u starého města patří k nejkrásnějším ve Skandinávii — právě tady byla roku 1397 podepsána Kalmarská unie spojující Švédsko, Dánsko a Norsko. Perfektní start okruhu, hned za hradem začíná nájezd na Ölandský most.', 56.6644, 16.3550, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalmar_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kalmar_slott.jpg"}'::text[], 0),
    (v_route, 'Ölandský most', 'Šest kilometrů dlouhý most z roku 1972 byl kdysi nejdelší v Evropě. Přejezd nad Kalmarským průlivem s výhledem na obě pobřeží je zážitek sám o sobě — jen se pevně drž, při silném západním větru to na vrcholu mostního oblouku pořádně fouká.', 56.6790, 16.4230, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%96landsbron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%96landsbron.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Hotell Borgholm (Borgholm)', 'Restaurace legendární šéfkuchařky Karin Fransson je gastronomickou institucí ostrova — moderní švédská kuchyně s bylinkami z vlastní zahrady. Borgholm je zároveň příjemné letoviskové městečko na kávu a procházku po přístavu.', 56.8800, 16.6560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Borgholms_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Borgholms_kyrka.jpg"}'::text[], 2),
    (v_route, 'Zřícenina Borgholm', 'Monumentální ruina barokního zámku na vápencovém ostrohu je největší hradní zříceninou severní Evropy. Vyhořel roku 1806 a od té doby stojí jako kulisa — koncertoval tu i Roxette. Kousek vedle je letní vila královské rodiny Solliden.', 56.8730, 16.6420, 'https://commons.wikimedia.org/wiki/Special:FilePath/Borgholms_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Borgholms_slott.jpg"}'::text[], 3),
    (v_route, 'Maják Långe Erik', 'Bílý kamenný maják z roku 1845 hlídá severní špici Ölandu u vesnice Byxelkrok. Cesta na sever vede kolem vápencových útvarů Byrums raukar a nejhezčích pláží ostrova. U majáku končí silnice — dál už je jen moře a ptáci.', 57.3690, 17.1030, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5nge_Erik.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5nge_Erik.jpg"}'::text[], 4),
    (v_route, 'Stora Alvaret', 'Největší vápencová step Evropy pokrývá čtvrtinu ostrova a je zapsaná na seznamu UNESCO. Silnička napříč alvarem u Möckelmossenu je surreálná jízda krajinou bez jediného stromu, kde kvetou orchideje a pasou se ovce. Zastav a vypni motor — to ticho stojí za to.', 56.5530, 16.5230, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stora_Alvaret.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stora_Alvaret.jpg"}'::text[], 5),
    (v_route, 'Maják Långe Jan (Ottenby)', 'Nejvyšší maják Skandinávie (42 m) stojí na jižním cípu ostrova uprostřed ptačí rezervace Ottenby — během tahů tu protahují miliony ptáků. Vyjdi 197 schodů nahoru, výhled na celý jižní Öland je odměnou.', 56.1975, 16.3995, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5nge_Jan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A5nge_Jan.jpg"}'::text[], 6);
