  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hradby Visby', 'Nejzachovalejší městské opevnění severní Evropy — 3,4 km hradeb s 27 věžemi obepíná hanzovní město plné růží, kostelních ruin a středověkých kupeckých domů. Celé Visby je na seznamu UNESCO. Projdi se po hradbách večer, kdy se z města vytratí denní návštěvníci.', 57.6410, 18.2920, 'https://commons.wikimedia.org/wiki/Special:FilePath/Visby_ringmur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Visby_ringmur.jpg"}'::text[], 0),
    (v_route, 'Jeskyně Lummelunda', 'Čtyřkilometrový jeskynní systém s krápníky a podzemní řekou, jedna z nejdelších jeskyní Švédska. Objevily ji ve 50. letech tři místní kluci — jejich příběh vypráví expozice u vchodu. Příjemné ochlazení v horkém dni, uvnitř je stálých 8 °C.', 57.7440, 18.4060, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lummelundagrottan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lummelundagrottan.jpg"}'::text[], 1),
    (v_route, 'Rauk Jungfrun (Lickershamn)', 'Panna — nejvyšší rauk Gotlandu, 12 metrů vysoká vápencová věž na útesu nad rybářskou vesničkou Lickershamn. Krátká procházka po pobřežní pěšině s výhledem na celé západní pobřeží. Podle legendy tu zkameněla dívka čekající na svého milého.', 57.8330, 18.5190, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lickershamn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lickershamn.jpg"}'::text[], 2),
    (v_route, 'Rauky Folhammar (Ljugarn)', 'Nejfotogeničtější raukové pole východního pobřeží — desítky vápencových věží přímo v příboji u letoviska Ljugarn. Při západu slunce vrhají skály dlouhé stíny přes oblázkovou pláž; ideální místo na piknik z místní pekárny.', 57.3430, 18.7280, 'https://commons.wikimedia.org/wiki/Special:FilePath/Folhammar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Folhammar.jpg"}'::text[], 3),
    (v_route, 'Hoburgsgubben', 'Stařec z Hoburgu — nejslavnější rauk Švédska na jižním mysu ostrova, který z profilu připomíná obří kamennou hlavu. Kolem útesy, maják a výhled na otevřené moře; sem už jezdí jen ti, kdo Gotland objedou celý. Silnička na mys je zábavně zvlněná.', 56.9210, 18.1440, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hoburgsgubben.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hoburgsgubben.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Bakfickan (Visby)', 'Legendární rybí bistro na hlavním náměstí Stora Torget uvnitř hradeb — čerstvé ryby a mušle z Baltu, žádné zbytečnosti. Večer si rezervuj místo, bývá plno. Perfektní tečka za okruhem ostrova.', 57.6366, 18.2932, 'https://commons.wikimedia.org/wiki/Special:FilePath/Visby_domkyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Visby_domkyrka.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Restaurace: Gyllene Uttern (Gränna)', 'Zlatá vydra — historický hostinec z roku 1935 na útesu vysoko nad Vätternem, s nejhezčí restaurační vyhlídkou celého okruhu. Klasická švédská kuchyně a okna přímo na jezero a ostrov Visingsö. Oblíbená zastávka motorkářů už po generace.', 58.0080, 14.4560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gyllene_Uttern.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gyllene_Uttern.jpg"}'::text[], 0),
    (v_route, 'Gränna – městečko polkagrisů', 'Malebné městečko pod útesem je rodištěm červenobílých mátových tyčinek polkagris — v desítce místních manufaktur uvidíš, jak se točí ručně, a ochutnáš je ještě teplé. Z přístavu jezdí trajekt na ostrov Visingsö s ruinami hradu rodu Brahe.', 58.0250, 14.4670, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%A4nna_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%A4nna_kyrka.jpg"}'::text[], 1),
    (v_route, 'Zřícenina Brahehus', 'Ruina zámku ze 17. století trůní na skále 260 metrů nad jezerem — výhled na Vättern a Visingsö patří k nejfotografovanějším ve Švédsku. Přístup je z odpočívky na E4, ale krásnější je stará silnička od Gränny.', 58.0410, 14.4670, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brahehus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brahehus.jpg"}'::text[], 2),
    (v_route, 'Vadstena – zámek a klášter', 'Renesanční vodní zámek Gustava Vasy a klášter svaté Birgitty dělají z Vadsteny duchovní i historické srdce Vätternu. Středověké uličky vedou přímo k jezernímu přístavu; zámecký příkop obývají labutě. Ideální delší pauza v půlce okruhu.', 58.4485, 14.8870, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vadstena_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vadstena_slott.jpg"}'::text[], 3),
    (v_route, 'Göta kanál (Motala)', 'V Motale, hlavním městě Göta kanálu, vplouvá slavná vodní cesta do Vätternu. Sleduj lodě v ručně obsluhovaných zdymadlech, projdi se po nábřeží, kde kanál lemují staré kapitánské vily, a mrkni do muzea motorismu s veterány.', 58.5390, 15.0300, 'https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%B6ta_kanal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%B6ta_kanal.jpg"}'::text[], 4),
    (v_route, 'Pevnost Karlsborg', 'Gigantická pevnost z 19. století měla být záložním hlavním městem Švédska — hradby dlouhé 5 km, kasárna pro 8 000 mužů a vlastní kostel. Stavěla se 90 let a po dokončení už byla vojensky zastaralá. Projet branami pevnosti na motorce je zážitek.', 58.5360, 14.5100, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karlsborgs_f%C3%A4stning.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlsborgs_f%C3%A4stning.jpg"}'::text[], 5),
    (v_route, 'Hjo – dřevěné městečko', 'Jedno ze tří švédských měst s ochrannou známkou za zachovalou dřevěnou zástavbu — pastelové vilky z 19. století, lázeňský park a přístav s parníkem Trafik z roku 1892. U jezera si dej zmrzlinu a kochej se výhledem přes Vättern na Omberg.', 58.3040, 14.2890, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hjo_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hjo_kyrka.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pevnost Carlsten (Marstrand)', 'Mohutná žulová pevnost ze 17. století korunuje ostrovní městečko Marstrand, kdysi nejhříšnější přístav Skandinávie. Na ostrov bez aut tě za pár minut přehoupne přívoz — motorku nech na hlídaném parkovišti. Z hradeb je výhled na celé souostroví.', 57.8860, 11.5810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Carlstens_f%C3%A4stning.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Carlstens_f%C3%A4stning.jpg"}'::text[], 0),
    (v_route, 'Most Tjörnbron', 'Elegantní zavěšený most se klene 45 metrů nad průlivem mezi ostrovy Stenungsön a Tjörn. Stojí na místě mostu, který se roku 1980 zřítil po nárazu lodi. Přejezd s výhledem na fjord plný plachetnic je jedním z vrcholů trasy.', 58.0107, 11.8330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tj%C3%B6rnbron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tj%C3%B6rnbron.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Salt & Sill (Klädesholmen)', 'Slavná plovoucí restaurace na ostrůvku Klädesholmen, sleďovém ostrově s bílými rybářskými domky. Ochutnávkové prkénko sleďů v šesti úpravách je povinnost — sem se jezdí na oběd z celého západního pobřeží. Rezervace v sezóně nutná.', 57.9440, 11.5480, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A4desholmen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A4desholmen.jpg"}'::text[], 2),
    (v_route, 'Smögenbryggan', 'Kilometr dlouhé dřevěné molo lemované pestrobarevnými rybářskými boudami je nejslavnější promenádou švédského západu. Kup si kornout čerstvých krevet přímo z lodi a najdi si místo na sluncem vyhřáté žule. V červenci žije molo do pozdní noci.', 58.3546, 11.2260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sm%C3%B6genbryggan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sm%C3%B6genbryggan.jpg"}'::text[], 3),
    (v_route, 'Fjällbacka', 'Rybářská vesnice sevřená mezi mořem a 74 metrů vysokou skálou Vetteberget, proslavená detektivkami Camilly Läckberg a milovaná Ingrid Bergmanovou, která tu trávila léta. Vyšlápni si rozsedlinou Kungsklyftan na vrchol skály — výhled na souostroví je fantastický.', 58.5990, 11.2840, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fj%C3%A4llbacka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fj%C3%A4llbacka.jpg"}'::text[], 4),
    (v_route, 'Skalní rytiny Vitlycke (UNESCO)', 'Tisíce rytin z doby bronzové — lodě, lovci, býci i slavný Svatební pár — pokrývají žulové plotny u Tanumu a jsou zapsané na seznamu UNESCO. Rytiny jsou zvýrazněné červenou barvou a hned vedle stojí moderní muzeum s rekonstrukcí vesnice z doby bronzové.', 58.7000, 11.3410, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vitlyckeh%C3%A4llen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vitlyckeh%C3%A4llen.jpg"}'::text[], 5),
    (v_route, 'Strömstad', 'Sluncem zalité lázeňské městečko pár kilometrů od norské hranice je cílem etapy — přístav plný lodí, žulové ostrůvky souostroví Koster na obzoru a nejvíc slunečních hodin ve Švédsku. Odsud se dá pokračovat rovnou do norského Osla.', 58.9380, 11.1710, 'https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6mstads_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6mstads_kyrka.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zorngården (Mora)', 'Dům a ateliér Anderse Zorna, nejslavnějšího švédského malíře, stojí v centru Mory přesně tak, jak ho s manželkou Emmou opustili. Vedlejší muzeum vystavuje jeho světoznámé akty a portréty — maloval i tři americké prezidenty. Mora je zároveň cílem legendárního Vasova běhu.', 61.0060, 14.5390, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zorng%C3%A5rden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zorng%C3%A5rden.jpg"}'::text[], 0),
    (v_route, 'Dřevění koníci v Nusnäs', 'Ve vesničce Nusnäs se už sto let ručně vyřezávají a malují červení koníci dalahäst — nejznámější suvenýr Švédska. V dílnách Nils Olsson Hemslöjd se můžeš dívat řezbářům přes rameno a koupit koníka rovnou od zdroje, klidně i metrového.', 60.9560, 14.6640, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dalah%C3%A4st.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dalah%C3%A4st.jpg"}'::text[], 1),
    (v_route, 'Rättvik – Långbryggan', 'Nejdelší dřevěné molo Švédska vybíhá 628 metrů do jezera — projdi se až na konec, kde kdysi přistávaly parníky. Nad břehem stojí středověký kostel obklopený sto padesáti roubenými stájemi, do kterých farníci odstavovali koně při nedělní mši.', 60.8790, 15.1120, 'https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A4ttviks_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A4ttviks_kyrka.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Klockargården (Tällberg)', 'Rodinný hotel s vyhlášenou kuchyní z místních surovin ve vesničce Tällberg, nejfotogeničtější obci u Siljanu — samé staleté roubenky s výhledem na jezero. Na zahradě se v létě peče chleba v kamenné peci a hraje folklor.', 60.8230, 15.0250, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A4llberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A4llberg.jpg"}'::text[], 3),
    (v_route, 'Leksand', 'Městečko na jižním cípu jezera je centrem dalarnského folkloru — o midsommaru tu staví největší májku ve Švédsku a k bohoslužbám se dodnes jezdí v dlouhých kostelních veslicích. Kostel s cibulovou bání nad ústím řeky Österdalälven patří k nejmalebnějším v zemi.', 60.7310, 14.9990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leksands_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Leksands_kyrka.jpg"}'::text[], 4),
    (v_route, 'Vyhlídka Gesundaberget', 'Z vrcholu hory nad západním břehem se otevírá nejlepší panorama celého kráteru Siljanu — jezero, ostrov Sollerön i lesy až k horizontu. Nahoru vede asfaltka k horní stanici lanovky. Pod horou leží vesnice Gesunda a přes hráze se dá přejet na ostrov Sollerön.', 60.9010, 14.5220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gesundaberget.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gesundaberget.jpg"}'::text[], 5),
    (v_route, 'Medvědí park Orsa', 'Největší medvědí park Evropy na svahu nad jezerem Orsasjön — medvědi hnědí, polární vlci, rysi i sibiřští tygři v obřích přírodních výbězích. Počítej aspoň se dvěma hodinami; areál Grönklitt nabízí i výhledovou restauraci.', 61.1550, 14.5220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orsa_Gr%C3%B6nklitt.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orsa_Gr%C3%B6nklitt.jpg"}'::text[], 6);
