  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Härnösand', 'Brána Vysokého pobřeží s bílou empírovou katedrálou, nejmenší ve Švédsku. Doplň nádrž a zásoby — na poloostrovech dál na severu už je obchodů málo. Ve městě sídlí i destilerie oceňovaného ginu Hernö.', 62.6323, 17.9379, 'https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4rn%C3%B6sands_domkyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4rn%C3%B6sands_domkyrka.jpg"}'::text[], 0),
    (v_route, 'Most Högakustenbron', 'Visutý most přes ústí řeky Ångermanälven s pylony vysokými 180 metrů je jedním z nejdelších na světě — hlavní pole měří 1210 metrů. Přejezd na motorce nad širokou řekou bere dech; nejlepší fotky jsou z vyhlídky u severního předmostí.', 62.7990, 17.9390, 'https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%B6gakustenbron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%B6gakustenbron.jpg"}'::text[], 1),
    (v_route, 'Mannaminne (Häggvik)', 'Svérázný skanzen umělce Anderse Åberga na poloostrově Nordingrå — desítky budov od norrlandských statků po maďarský kostelík, plné lodí, aut a kuriozit. Kavárna s domácími koláči a výhledem na záliv je ideální dopolední pauza.', 62.9640, 18.1900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mannaminne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mannaminne.jpg"}'::text[], 2),
    (v_route, 'Norrfällsviken', 'Rybářská vesnice na samém konci poloostrova — červené boudy z 16. století, kaple na skále a hladké žulové plotny, po kterých se dá dojít až k moři. V místní udírně kup zauzeného lososa; tady chutná Vysoké pobřeží nejlíp.', 62.9640, 18.2620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Norrf%C3%A4llsviken.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Norrf%C3%A4llsviken.jpg"}'::text[], 3),
    (v_route, 'Skuleberget', 'Skalní stěna nad Docksta, symbol Vysokého pobřeží — na vrchol 295 metrů nad mořem vede sedačková lanovka i via ferrata. Kdysi to byl mořský útes; dnes z vrcholu přehlédneš celé souostroví. U paty hory je návštěvnické centrum s expozicí o zdvihu pevniny.', 63.0670, 18.3560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skuleberget.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skuleberget.jpg"}'::text[], 4),
    (v_route, 'Slåttdalsskrevan (NP Skuleskogen)', 'Čtyřicet metrů hluboká a jen sedm metrů široká skalní rozsedlina je nejslavnějším místem národního parku Skuleskogen. Od západního vstupu k ní vede značená stezka pralesem a po žulových plotnách, tam a zpět asi dvě hodiny — pohorky s sebou, odměnou je výhled na záliv z náhorní plošiny.', 63.0870, 18.5330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sl%C3%A5ttdalsskrevan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sl%C3%A5ttdalsskrevan.jpg"}'::text[], 5);
