  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Karlstad', 'Město u ústí Klarälvenu do Vänernu má ve znaku usměvavé slunce — je prý nejslunečnější ve Švédsku. Před startem se projdi po nábřeží k nejdelšímu kamennému mostu v zemi, dvanáctiobloukovému Östra bron z 18. století.', 59.3793, 13.5036, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karlstads_domkyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlstads_domkyrka.jpg"}'::text[], 0),
    (v_route, 'Mårbacka – statek Selmy Lagerlöfové', 'Rodný statek první ženy s Nobelovou cenou za literaturu, autorky Podivuhodné cesty Nilse Holgerssona. Bílý dům s empírovým sloupovím si nechala přestavět z honoráře a dodnes je zařízený, jak ho roku 1940 opustila. Kavárna na zahradě peče podle jejích receptů.', 59.7620, 13.2680, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A5rbacka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A5rbacka.jpg"}'::text[], 1),
    (v_route, 'Park Rottneros', 'Zámecký park se čtyřiceti hektary zahrad a stovkou soch — Milles, Vigeland i antické kopie mezi rododendrony nad jezerem Fryken. Zámek Rottneros je předobrazem Ekeby z Gösty Berlinga Selmy Lagerlöfové.', 59.7940, 13.1160, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rottneros_Park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rottneros_Park.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Broby Gästgivaregård (Sunne)', 'Historický zájezdní hostinec v centru Sunne vaří poctivou värmlandskou kuchyni — losí maso, síh z Frykenu a domácí moučníky. Hostinec tu stojí od 17. století a je ideální obědovou zastávkou v půlce okruhu.', 59.8360, 13.1430, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunne_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sunne_kyrka.jpg"}'::text[], 3),
    (v_route, 'Vyhlídka Tossebergsklätten', 'Skalní vrch 343 metrů nad jezerem Fryken s kruhovým výhledem na celé údolí — v jasném dni dohlédneš přes tři jezera až k norské hranici. Nahoru vede úzká asfaltka plná serpentin, nejzábavnější kilometry celého okruhu. V románu Gösta Berling se vrch jmenuje Gurlita.', 59.9410, 13.0650, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tossebergskl%C3%A4tten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tossebergskl%C3%A4tten.jpg"}'::text[], 4),
    (v_route, 'Kostel v Ekshäradu', 'Dřevěný kostel z roku 1688 nad Klarälvenem proslavil hřbitov s unikátními kovanými kříži ve tvaru stromů života — stovky jich tu zvoní ve větru. Jedno z nejzvláštnějších a nejatmosféričtějších míst Värmlandu.', 60.1730, 13.4920, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eksh%C3%A4rads_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eksh%C3%A4rads_kyrka.jpg"}'::text[], 5),
    (v_route, 'Meandry řeky Klarälven', 'Silnice 62 na jihu údolí kopíruje líné meandry řeky, po které se až do roku 1991 plavily klády — poslední splavovaná řeka Švédska. U Ransäteru stojí rodný statek skladatele a historika Erika Gustafa Geijera a v létě se tu dá půjčit vor a splout kus řeky po vzoru starých vorařů.', 59.7770, 13.4260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klar%C3%A4lven.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klar%C3%A4lven.jpg"}'::text[], 6);
