  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Gamla stan (Stockholm)', 'Staré město na ostrově mezi jezerem Mälaren a Baltem — křivolaké středověké uličky, královský palác a náměstí Stortorget s barevnými kupeckými domy. Vyraž brzy ráno, dokud jsou uličky prázdné, a pak už rovnou po mostech na východ do souostroví.', 59.3251, 18.0711, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stockholm_old_town_2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stockholm_old_town_2002.jpg"}'::text[], 0),
    (v_route, 'Pevnost Vaxholm', 'Kruhová pevnost z 19. století na ostrůvku uprostřed úžiny střežila lodní cestu do Stockholmu už od dob Gustava Vasy — odrazila Dány i ruskou flotilu. Z nábřeží Vaxholmu k ní pendluje malý přívoz; městečko samotné je plné dřevěných secesních vil a kaváren.', 59.4030, 18.3600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kastell.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kastell.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Hembygdsgårdens Café (Vaxholm)', 'Kultovní kavárna ve staré rybářské usedlosti přímo u vody s výhledem na pevnost — domácí skořicoví šneci a princezdorty patří k nejlepším v okolí Stockholmu. V létě se sedí na skalách u mola.', 59.4060, 18.3560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms_kyrka.jpg"}'::text[], 2),
    (v_route, 'Gustavsberg – porcelánka', 'Přístavní čtvrť kolem slavné porcelánky z roku 1825, kde vznikal servis pro švédský královský dvůr. Dnes tu najdeš muzeum porcelánu, továrenské outlety, keramické ateliéry a kavárny ve starých tovární halách u zálivu.', 59.3270, 18.3860, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gustavsbergs_hamn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gustavsbergs_hamn.jpg"}'::text[], 3),
    (v_route, 'Dalarö', 'Bývalá celnice a kapitánská vesnice ze 17. století na skalách nad průlivem — dřevěné vily se zdobenými verandami, malý přístav a atmosféra starých časů souostroví. Ve vodách kolem leží desítky vraků včetně slavné lodi Anna Maria z roku 1709, ráj potápěčů.', 59.1320, 18.4080, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dalar%C3%B6_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dalar%C3%B6_kyrka.jpg"}'::text[], 4),
    (v_route, 'Nynäshamn', 'Přístavní město na jižním cípu souostroví, odkud vyplouvají trajekty na Gotland i do Polska. V přístavní tržnici u mola dostaneš vyhlášené uzené ryby — ideální závěr dne s výhledem na vyplouvající lodě, než se vrátíš po rychlé 73 do Stockholmu.', 58.9030, 17.9480, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nyn%C3%A4shamns_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nyn%C3%A4shamns_kyrka.jpg"}'::text[], 5);
