  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vodopády a zdymadla Trollhättan', 'Řeka Göta älv tu padá o 32 metrů — když se v určené časy otevřou stavidla elektrárny, valí se kaňonem 300 000 litrů za sekundu a země se chvěje. Hned vedle stoupá kaskáda zdymadel Trollhätte kanálu ze tří staletí. Průmyslová romantika, jakou jinde nezažiješ.', 58.2760, 12.2720, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trollh%C3%A4ttefallen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trollh%C3%A4ttefallen.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Albert Kök (Trollhättan)', 'Restaurace ve vile z 19. století na skále přímo nad kanálem — moderní švédská kuchyně a terasa s výhledem na proplouvající lodě. Skvělé místo na pozdní oběd po návratu z okruhu, kuchyně patří k nejlepším v západním Švédsku.', 58.2700, 12.2740, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trollh%C3%A4ttans_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trollh%C3%A4ttans_kyrka.jpg"}'::text[], 1),
    (v_route, 'Lidköping', 'Město u zálivu Kinneviken s jedním z největších náměstí Švédska, kterému vévodí dřevěná radnice — původně lovecký zámeček přenesený sem roku 1672. Lidköping je domovem porcelánky Rörstrand, druhé nejstarší v Evropě, s muzeem a outletem.', 58.5035, 13.1577, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lidk%C3%B6pings_r%C3%A5dhus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lidk%C3%B6pings_r%C3%A5dhus.jpg"}'::text[], 2),
    (v_route, 'Zámek Läckö', 'Bílý barokní zámek na skále nad hladinou Vänernu vypadá jako z pohádky — 250 komnat, hradní zahrada a přístav s plachetnicemi pod hradbami. Silnička na Kållandsö mezi zálivy a rybářskými vesničkami je zážitek sama o sobě; kousek před zámkem leží rybářský přístav Spiken s udírnami.', 58.6740, 13.2210, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A4ck%C3%B6_slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A4ck%C3%B6_slott.jpg"}'::text[], 3),
    (v_route, 'Stolová hora Kinnekulle', 'Rozkvetlá hora — 306 metrů vysoká stolová hora nad Vänernem s vyhlídkovou věží na vrcholu, kam vede příjemná lesní asfaltka. Na jaře kvetou svahy třešněmi a medvědím česnekem; z věže přehlédneš jezero až k obzoru. Po cestě dolů stavěj u starých vápencových lomů.', 58.5950, 13.3970, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kinnekulle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kinnekulle.jpg"}'::text[], 4),
    (v_route, 'Kostel v Husaby', 'Kamenný kostel s mohutnou trojvěžovou západní věží z 11. století je kolébkou švédského křesťanství — u zdejšího pramene byl kolem roku 1000 pokřtěn první švédský král Olof Skötkonung. Jeho hrob najdeš hned u zdi kostela.', 58.5380, 13.3820, 'https://commons.wikimedia.org/wiki/Special:FilePath/Husaby_kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Husaby_kyrka.jpg"}'::text[], 5);
